#!/usr/bin/env bash
# Pure Java tests use generated bytes and do not require an Android device.
set -euo pipefail
repo=$(cd -- "$(dirname -- "$0")/.." && pwd)
java_bin=${JAVA_HOME:+"$JAVA_HOME/bin/"}
classes=$(mktemp -d)
trap 'rm -rf -- "$classes"' EXIT
"${java_bin}javac" -encoding UTF-8 -source 8 -target 8 -Xlint:-options -d "$classes" \
  "$repo/android/app/java/org/rigelengineproton/android/GameDataImporter.java" \
  "$repo/android/test/GameDataImporterTest.java"
"${java_bin}java" -cp "$classes" org.rigelengineproton.android.GameDataImporterTest
